-- Dador de Misiones
lang["#MISSION_GIVER_80SMAX"] = "Saqueador de Caravanas Max"
lang["#MISSION_GIVER_80SMAX_SUBTITLE"] = "Tribu de los 80"
lang["#MISSION_GIVER_80SMAX_GREET_NEW"] = "Oye tú, ¿nuevo por aquí? En realidad, no respondas, no me importa. Mientras podamos deleitarnos con el sufrimiento de esos bastardos de las caravanas, quién seas no importa. ¿Te sientes capaz de la tarea?\n\n\nAquí tienes una lista de cosas con las que necesito ayuda."
lang["#MISSION_GIVER_80SMAX_GREET_N100"] = "*escupitajo*"
lang["#MISSION_GIVER_80SMAX_GREET_0"] = "$playername, ¿qué estás haciendo? Cuanto más esperes, más se llenan los bolsillos esos cerdos. Ponte a trabajar."
lang["#MISSION_GIVER_80SMAX_GREET_100"] = "Justo a quien necesitaba ver, $playername. Tengo un trabajo para ti."
lang["#MISSION_GIVER_80SMAX_GREET_FINISHED"] = "Mira quién está aquí, el azote de las caravanas en persona. Las caravanas se han estado moviendo con discreción ahora, no tengo más para ti."

-- Misiones
lang["#MISSION_80SMAX_PERSONALREQUEST"] = "Robo de Madera"
lang["#MISSION_80SMAX_PERSONALREQUEST_DESC"] = "Se dice por la zona que la Caravana Carmesí está buscando restos de madera para dárselos a un cliente VIP. Asegúrate de que no la encuentren."
lang["#MISSION_80SMAX_PERSONALREQUEST_HINT"] = "Obtén Restos de Madera. Se puede recolectar, rescatar o recoger de otros manojos de madera / árboles rotos. También puedes comprarla a algunos comerciantes."
lang["#MISSION_80SMAX_PERSONALREQUEST_COMPLETE"] = "Ja, buen trabajo, puedo imaginar a ese idiota de Isaac entrando en pánico. Aquí tienes tu recompensa."

lang["#MISSION_80SMAX_LEATHERYORDER"] = "Robo de Cuero"
lang["#MISSION_80SMAX_LEATHERYORDER_DESC"] = "Los rumores dicen que la Caravana Carmesí ha recibido ahora un pedido de cuero, asegúrate de que no haya ninguno."
lang["#MISSION_80SMAX_LEATHERYORDER_HINT"] = "Obtén Cuero. Se puede encontrar saqueando, rescatando objetos de cuero o comprándolo a comerciantes."
lang["#MISSION_80SMAX_LEATHERYORDER_COMPLETE"] = "Supongo que ese tipo tendrá que conformarse con una chaqueta de tela."

lang["#MISSION_80SMAX_MEDICINALS"] = "Caza de Stimpaks"
lang["#MISSION_80SMAX_MEDICINALS_DESC"] = "Hay más peleas ocurriendo en la zona regularmente, lo que significa que ese tonto de Isaac ciertamente intentará hacer su agosto con los stimpaks. ¿Por qué no se lo ponemos más difícil?"
lang["#MISSION_80SMAX_MEDICINALS_HINT"] = "Obtén Stimpaks. Se pueden saquear, fabricar o comprar a comerciantes."
lang["#MISSION_80SMAX_MEDICINALS_COMPLETE"] = "Un dólar robado es un dólar ganado, eso seguro."

lang["#MISSION_80SMAX_METALBULK"] = "Malversación de Metal"
lang["#MISSION_80SMAX_METALBULK_DESC"] = "Otro cliente importante de la Caravana Carmesí les ha hecho un pedido urgente de metal. Haz que todo desaparezca."
lang["#MISSION_80SMAX_METALBULK_HINT"] = "Obtén Chatarra Metálica. Se encuentra fácilmente rescatando vehículos y saqueando. También se puede obtener descomponiendo objetos relacionados con metal."
lang["#MISSION_80SMAX_METALBULK_COMPLETE"] = "Empiezas a recordarme a mí mismo. Toma tu recompensa."

-- T2

lang["#MISSION_80SMAX_SHARPTOOLS"] = "Cleptomanía de Cuchillos"
lang["#MISSION_80SMAX_SHARPTOOLS_DESC"] = "La Caravana Carmesí acaba de recibir un pedido de un cuchillo de combate, róbalo. Esta vez ni siquiera lo quiero, pero tampoco quiero que Isaac lo tenga."
lang["#MISSION_80SMAX_SHARPTOOLS_HINT"] = "Obtén un Cuchillo de Combate. Los venden los comerciantes."
lang["#MISSION_80SMAX_SHARPTOOLS_COMPLETE"] = "Eso es un cuchillo, seguro. Toma tu dinero."

lang["#MISSION_80SMAX_GOODHIDES"] = "Manía de Ratas Topo"
lang["#MISSION_80SMAX_GOODHIDES_DESC"] = "Isaac está tratando de encontrar ratas topo, quién sabe por qué, pero lo importante es que las encuentres tú primero."
lang["#MISSION_80SMAX_GOODHIDES_HINT"] = "Obtén Pieles de Rata Topo. Puedes obtener pieles matando y saqueando Ratas Topo."
lang["#MISSION_80SMAX_GOODHIDES_COMPLETE"] = "¿Y qué voy a hacer yo con estas?"

lang["#MISSION_80SMAX_LOADOUT"] = "Sangre Nueva"
lang["#MISSION_80SMAX_LOADOUT_DESC"] = "Hay un novato, muy parecido a como tú eras hace poco. Sé que yo no te di nada, pero este tipo realmente parece necesitar ayuda. Encuéntrale un equipo inicial."
lang["#MISSION_80SMAX_LOADOUT_HINT"] = "Obtén una Pistola 9mm, Munición 9mm y un Abrigo de Mercenario. Las Pistolas 9mm y su munición rara vez se encuentran saqueando y se compran a comerciantes. Los Abrigos de Mercenario son vendidos comúnmente por comerciantes."
lang["#MISSION_80SMAX_LOADOUT_COMPLETE"] = "Bueno, esperemos que este tipo dure al menos una semana antes de morir."

lang["#MISSION_80SMAX_COUPLESMOKES"] = "Piratería de Cigarrillos"
lang["#MISSION_80SMAX_COUPLESMOKES_DESC"] = "Los cigarrillos son uno de los productos más vendidos. Hace tiempo que no fumo, pero fumaría 20 paquetes al día si con eso Isaac no pudiera venderlos. Encuéntrame algunos paquetes."
lang["#MISSION_80SMAX_COUPLESMOKES_HINT"] = "Obtén 4 Paquetes de Cigarrillos. Se pueden encontrar saqueando."
lang["#MISSION_80SMAX_COUPLESMOKES_COMPLETE"] = "*tose* Aquí tienes tu dinero."

lang["#MISSION_80SMAX_PREWARSNACKS"] = "Aperitivos a Escondidas"
lang["#MISSION_80SMAX_PREWARSNACKS_DESC"] = "La Caravana Carmesí busca comida de antes de la guerra. No hay mucha en la zona, así que debería ser fácil privarles de ella."
lang["#MISSION_80SMAX_PREWARSNACKS_HINT"] = "Obtén Patatas Fritas, Instapuré, Algodón de Azúcar y Pastelitos. Todos se pueden encontrar saqueando y a veces los venden los comerciantes."
lang["#MISSION_80SMAX_PREWARSNACKS_COMPLETE"] = "Mi estómago no va a disfrutar esto."

-- T3

lang["#MISSION_80SMAX_CARREPAIR"] = "Reparación de Motos"
lang["#MISSION_80SMAX_CARREPAIR_DESC"] = "Esos idiotas del pueblo están intentando reparar un coche, convenientemente nuestras motos también necesitan algunas reparaciones. Encuentra esas piezas antes que ellos."
lang["#MISSION_80SMAX_CARREPAIR_HINT"] = "Obtén Baterías Improvisadas y Ruedas. Las Baterías Improvisadas se pueden fabricar en bancos de trabajo. Las Ruedas también se pueden fabricar en bancos de trabajo o encontrarse en vehículos desguazados."
lang["#MISSION_80SMAX_CARREPAIR_COMPLETE"] = "Esta vez puedo decir que lo has hecho bien, esto ayudará a la tribu y no solo a mí. Toma tu recompensa."

lang["#MISSION_80SMAX_FIBERS"] = "Filbando Fibras"
lang["#MISSION_80SMAX_FIBERS_DESC"] = "Esta vez es más urgente que nuestro habitual sabotaje mezquino. La Caravana Carmesí está tratando de encontrar fibras balísticas militares, estas fibras no pueden caer en sus manos."
lang["#MISSION_80SMAX_FIBERS_HINT"] = "Obtén 4 Fibras Balísticas. Se pueden encontrar en contenedores de munición o armarios militares."
lang["#MISSION_80SMAX_FIBERS_COMPLETE"] = "¿De verdad las encontraste antes que ellos? Iban en serio con esto, increíble. Toma tu recompensa."

lang["#MISSION_80SMAX_FACTORYMATERIALS"] = "Materiales de Fábrica"
lang["#MISSION_80SMAX_FACTORYMATERIALS_DESC"] = "Me han soplado que Isaac tiene otro gran pedido importante, esta vez es una cantidad significativa de materiales. ¿Por qué no le haces la vida un infierno?"
lang["#MISSION_80SMAX_FACTORYMATERIALS_HINT"] = "Obtén Lingotes de Plomo, Lingotes de Cobre y Material Nuclear. Los Lingotes de Plomo y Cobre se pueden encontrar saqueando y a veces los venden los comerciantes. El Material Nuclear se puede encontrar saqueando."
lang["#MISSION_80SMAX_FACTORYMATERIALS_COMPLETE"] = "¿Eso brilla? ¿Qué demonios está intentando vender Isaac?"

lang["#MISSION_80SMAX_SPECIALKINDOFHIDE"] = "Caza Furtiva de Sanguinarios"
lang["#MISSION_80SMAX_SPECIALKINDOFHIDE_DESC"] = "Isaac tiene chicos de recados corriendo por todas partes tratando de conseguir una piel de sanguinario. Creo que todo nuestro sabotaje finalmente está poniendo en peligro su posición. Ve a hacérselo más difícil una vez más."
lang["#MISSION_80SMAX_SPECIALKINDOFHIDE_HINT"] = "Obtén Piel de Sanguinario. Puedes obtenerla si tienes la ventaja de desollar escamas y logras matar a un Sanguinario."
lang["#MISSION_80SMAX_SPECIALKINDOFHIDE_COMPLETE"] = "¿Lograste encontrar una piel? Sinceramente, no pensé que pudieras hacerlo con la mano de obra que Isaac tenía buscándola."

lang["#MISSION_80SMAX_RAIDEREMPORIUMGRANDDOPENING"] = "¡Emporio del Saqueador de Caravanas!"
lang["#MISSION_80SMAX_RAIDEREMPORIUMGRANDDOPENING_DESC"] = "Con Isaac fuera de escena, ¡finalmente puedo robarle su negocio! Por un precio bajo, puedo dejarte echar un vistazo a todas las mercancías que he acumulado en mi tiempo como saqueador."
lang["#MISSION_80SMAX_RAIDEREMPORIUMGRANDDOPENING_HINT"] = "Obtén 20000 Dólares de la RNC y 25000 Tapas de Botella y regresa con Max."
lang["#MISSION_80SMAX_RAIDEREMPORIUMGRANDDOPENING_COMPLETE"] = "Aquí tienes la llave $playername, el emporio está abierto ahora. ¡Compra hasta que se te acabe el corazón!"

RELOADSCHEMA = true
